def _validate_migration_compare_result(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], list[dict]]:
    """Validate a complete :func:`compare_migration` result.

    Returns the fresh ``names`` and ``groups`` axes and the data rows
    in groups order, checking the ``climate-grid/mc2-v1`` contract:
    key order, the schema, the names and groups axes, the
    groups-order rows and the internal
    ``n``/``missing``/``span``/``agreement``/``uncertainty``
    invariants of every row.  ``span``, ``agreement`` and
    ``uncertainty`` are ``None`` together and must be ``None`` when
    ``n`` is zero; when present ``span`` is a non-bool int,
    ``agreement`` is between 0 and 1 and ``uncertainty`` is
    non-negative, both rounded to 12 digits.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _MIGRATION_COMPARE_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, names, groups, "
            "data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _MIGRATION_COMPARE_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_MIGRATION_COMPARE_SCHEMA!r}"
        )

    names = _validate_string_list(result["names"], f"{where}.names", minimum=2)
    groups = _validate_string_list(
        result["groups"], f"{where}.groups", minimum=1
    )

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) != len(groups):
        raise ValueError(
            f"{where}.data must contain exactly one row per group"
        )

    total = len(names)
    out_rows: list[dict] = []
    for row_index, row in enumerate(data):
        row_where = f"{where}.data[{row_index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _MIGRATION_COMPARE_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys group, n, missing, "
                "span, agreement, uncertainty in order"
            )

        group = row["group"]
        if not isinstance(group, str):
            raise TypeError(f"{row_where}.group must be a str")
        expected_group = groups[row_index]
        if group != expected_group:
            raise ValueError(
                f"{row_where}.group {group!r} must follow groups order "
                f"(expected {expected_group!r})"
            )

        n = row["n"]
        if not isinstance(n, int) or isinstance(n, bool):
            raise TypeError(f"{row_where}.n must be a non-bool int")
        if not 0 <= n <= total:
            raise ValueError(
                f"{row_where}.n must be between 0 and the number of names"
            )

        missing = row["missing"]
        if not isinstance(missing, int) or isinstance(missing, bool):
            raise TypeError(f"{row_where}.missing must be a non-bool int")
        if missing != total - n:
            raise ValueError(
                f"{row_where}.missing must equal the number of names minus n"
            )

        span = row["span"]
        agreement = row["agreement"]
        uncertainty = row["uncertainty"]
        present = [value is not None for value in (span, agreement, uncertainty)]
        if any(present) and not all(present):
            raise ValueError(
                f"{row_where}.span, {row_where}.agreement and "
                f"{row_where}.uncertainty must be None together"
            )
        if not any(present):
            if n < 0:
                raise ValueError(f"{row_where}.n must be non-negative")
            out_rows.append(row)
            continue

        if n < 1:
            raise ValueError(
                f"{row_where}.span, {row_where}.agreement and "
                f"{row_where}.uncertainty must be None when n is zero"
            )
        if not isinstance(span, int) or isinstance(span, bool):
            raise TypeError(f"{row_where}.span must be a non-bool int or None")
        if span < 0:
            raise ValueError(f"{row_where}.span must be non-negative")

        _validate_number(
            agreement, f"{row_where}.agreement", nullable=False
        )
        if not 0 <= agreement <= 1:
            raise ValueError(
                f"{row_where}.agreement must be between 0 and 1"
            )
        if agreement != _round_output(agreement):
            raise ValueError(
                f"{row_where}.agreement must be rounded to 12 digits"
            )

        _validate_number(
            uncertainty, f"{row_where}.uncertainty", nullable=False
        )
        if uncertainty < 0:
            raise ValueError(
                f"{row_where}.uncertainty must be non-negative"
            )
        if uncertainty != _round_output(uncertainty):
            raise ValueError(
                f"{row_where}.uncertainty must be rounded to 12 digits"
            )

        out_rows.append(row)

    return names, groups, out_rows


